use narrative_lens::{
    continuity::entity::{CorrectionAction, EntityCorrection},
    manuscript::*,
    onnx::{
        checked::ModelKind,
        model::{ModelIdentity, ModelManifest, ModelProfile, ModelVerification},
    },
    structure::genre::Genre,
};
use std::{fs, path::Path};
use ts_rs::{Config, TS};
fn declaration<T: TS>(config: &Config) -> String {
    format!("export {}\n", T::decl(config))
}
fn main() {
    let check = std::env::args().any(|s| s == "--check");
    let config = Config::default().with_large_int("number");
    let mut types = String::from(
        "// Generated by cargo run --features bindings --example export_contracts.\n// Edit Rust contracts and regenerate; do not edit this file.\n\n",
    );
    macro_rules! emit{($($t:ty),* $(,)?)=>{$(types.push_str(&declaration::<$t>(&config));)*};}
    emit!(
        RuleId,
        RuleMethod,
        Severity,
        Intention,
        ModelPolicy,
        ModelKind,
        ModelProfile,
        ModelManifest,
        ModelVerification,
        ModelIdentity,
        AnalysisLimits,
        Thresholds,
        Configuration,
        Suppression,
        Genre,
        EntityCorrection,
        CorrectionAction,
        Chronology,
        Scene,
        Manuscript,
        TextRange,
        EvidenceContext,
        EvidenceRole,
        Evidence,
        ConfidenceSource,
        Confidence,
        Scope,
        Finding,
        Status,
        Coverage,
        Diagnostic,
        SceneMetrics,
        SuppressedFinding,
        ReaderKnowledge,
        ChronologyReport,
        ReportSummary,
        Report,
        MatchKind,
        ChangeDirection,
        UnassessedFinding,
        PersistentFinding,
        RevisionComparison,
        CacheStats,
        RuleDefinition
    );
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    let schemas = serde_json::json!({"Manuscript":schemars::schema_for!(Manuscript),"Report":schemars::schema_for!(Report),"RevisionComparison":schemars::schema_for!(RevisionComparison),"Configuration":schemars::schema_for!(Configuration)});
    for (path, contents) in [
        (root.join("manuscript.generated.d.ts"), types),
        (
            root.join("docs/manuscript.schema.json"),
            format!("{}\n", serde_json::to_string_pretty(&schemas).unwrap()),
        ),
    ] {
        if check {
            assert_eq!(
                fs::read_to_string(&path).expect("generated contract missing"),
                contents,
                "{} is stale; run export_contracts",
                path.display()
            );
        } else {
            fs::write(path, contents).unwrap();
        }
    }
}
